    questionText: "Explain the role of each class.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 25,
    rows: [
    { id: "r-1", kind: "point", verbatim: "The Rulers who love the truth and knowledge, are naturally suited to be the rulers of the state", marks: null },
    { id: "r-2", kind: "point", verbatim: "The Auxiliaries who love courage, honour and their homeland, must protect and defend the state", marks: null },
    { id: "r-3", kind: "point", verbatim: "The Workers love security, the fruits of their labours and are concerned with providing comfort and material and well-being", marks: null },
    { id: "r-4", kind: "point", verbatim: "They produce the goods and services needed by the state", marks: null },
    { id: "r-5", kind: "point", verbatim: "Each member of the state should be doing the job to which they are most suited and most capable", marks: null },
    { id: "r-6", kind: "point", verbatim: "Each group must limit itself to its own proper function and not interfere with the functions of the other groups", marks: null },
    { id: "r-7", kind: "point", verbatim: "If this is not so, things are out of balance", marks: null },
    ],
